def list_departments(status=None, source=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0211000" if __import__("os").path.isdir("./environment_mix/0211000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(dt):
        if dt is None:
            return None
        if not isinstance(dt, str):
            return None
        try:
            if dt.endswith("Z"):
                return datetime.datetime.fromisoformat(dt[:-1])
            return datetime.datetime.fromisoformat(dt)
        except Exception:
            return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _load_request_log():
        # Prefer a service-wide request log if present; otherwise create a local one.
        # This keeps "observable service dynamics" without requiring schema changes elsewhere.
        fname = "request_log.json"
        path = os.path.join(_DB, fname)
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, list):
                    return fname, data
        except Exception:
            return fname, []
        return fname, []

    def _save_request_log(fname, data):
        _save(fname, data)

    def _record_call(endpoint, params, status_code, error_code=None, error_message=None, extra=None, started_at=None):
        fname, logs = _load_request_log()
        ended = time.time()
        latency_ms = None
        if started_at is not None:
            latency_ms = int(round((ended - started_at) * 1000))
        row = {
            "id": "req_" + _stable_hash(f"{endpoint}|{_now()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "latency_ms": latency_ms,
            "params": params,
        }
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        if extra:
            row.update(extra)
        logs.append(row)
        _save_request_log(fname, logs)

    def _validate():
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "inactive"):
                return _err("VALIDATION_ERROR", "Invalid status.", field="status")
        if source is not None:
            if not isinstance(source, str) or source != "met_api":
                return _err("VALIDATION_ERROR", "Invalid source.", field="source")
        lim = 50 if limit is None else limit
        if not isinstance(lim, int):
            return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
        if lim < 1 or lim > 200:
            return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        srt = "displayName" if sort is None else sort
        if not isinstance(srt, str) or srt not in ("displayName", "createdAt", "updatedAt"):
            return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")
        ordv = "asc" if order is None else order
        if not isinstance(ordv, str) or ordv not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "Invalid order.", field="order")
        return None, lim, srt, ordv

    def _encode_cursor(payload_dict):
        raw = json.dumps(payload_dict, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        try:
            pad = "=" * ((4 - (len(cur) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    started = time.time()
    endpoint = "list-departments"
    params_for_log = {
        "status": status,
        "source": source,
        "limit": limit,
        "cursor": cursor,
        "sort": sort,
        "order": order,
    }

    try:
        v = _validate()
        if isinstance(v, dict) and "error" in v:
            _record_call(endpoint, params_for_log, 400, v["error"]["code"], v["error"]["message"], started_at=started)
            return v
        err, lim, srt, ordv = v
        if err is not None:
            _record_call(endpoint, params_for_log, 400, err["error"]["code"], err["error"]["message"], started_at=started)
            return err

        departments = _load("departments.json")
        if not isinstance(departments, list):
            departments = []

        # Default behavior per business rule: tool reads active departments ordered by met_department_id.
        # The vendor tool supports optional status/source/sort/order; if status not provided, default to active.
        eff_status = status if status is not None else "active"

        rows = []
        for d in departments:
            if not isinstance(d, dict):
                continue
            if eff_status is not None and d.get("status") != eff_status:
                continue
            if source is not None and d.get("source") != source:
                continue
            rows.append(d)

        # Map sort keys
        def _sort_key(row):
            if srt == "displayName":
                v = row.get("display_name")
                return ("" if v is None else str(v).lower(), str(row.get("met_department_id") or 0), row.get("id") or "")
            if srt == "createdAt":
                dt = _parse_iso(row.get("created_at"))
                return (dt or datetime.datetime.min, row.get("id") or "")
            if srt == "updatedAt":
                dt = _parse_iso(row.get("updated_at"))
                return (dt or datetime.datetime.min, row.get("id") or "")
            v = row.get("display_name")
            return ("" if v is None else str(v).lower(), row.get("id") or "")

        reverse = (ordv == "desc")
        rows.sort(key=_sort_key, reverse=reverse)

        # Cursor is an opaque offset token tied to the effective filters/sort/order.
        offset = 0
        if cursor:
            decoded = _decode_cursor(cursor)
            if not decoded:
                e = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
                _record_call(endpoint, params_for_log, 400, e["error"]["code"], e["error"]["message"], started_at=started)
                return e
            if decoded.get("v") != 1:
                e = _err("VALIDATION_ERROR", "Invalid cursor version.", field="cursor")
                _record_call(endpoint, params_for_log, 400, e["error"]["code"], e["error"]["message"], started_at=started)
                return e
            expected_sig = _stable_hash(json.dumps({
                "status": eff_status,
                "source": source,
                "sort": srt,
                "order": ordv
            }, separators=(",", ":"), ensure_ascii=False))
            if decoded.get("sig") != expected_sig:
                e = _err("VALIDATION_ERROR", "Cursor does not match request parameters.", field="cursor")
                _record_call(endpoint, params_for_log, 400, e["error"]["code"], e["error"]["message"], started_at=started)
                return e
            off = decoded.get("offset")
            if not isinstance(off, int) or off < 0:
                e = _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")
                _record_call(endpoint, params_for_log, 400, e["error"]["code"], e["error"]["message"], started_at=started)
                return e
            offset = off

        total = len(rows)
        page = rows[offset: offset + lim]
        next_cursor = None
        has_more = (offset + lim) < total
        if has_more:
            sig = _stable_hash(json.dumps({
                "status": eff_status,
                "source": source,
                "sort": srt,
                "order": ordv
            }, separators=(",", ":"), ensure_ascii=False))
            next_cursor = _encode_cursor({"v": 1, "offset": offset + lim, "sig": sig})

        resp = {
            "data": page,
            "meta": {
                "total": total,
                "limit": lim,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "cursor": cursor,
                "sort": srt,
                "order": ordv,
                "status": eff_status,
                "source": source,
            }
        }
        _record_call(endpoint, params_for_log, 200, started_at=started)
        return resp
    except Exception as ex:
        # Unexpected programming/runtime error: return error object (must not raise).
        e = _err("CONFLICT", "Internal error.", detail=str(ex))
        _record_call(endpoint, params_for_log, 500, e["error"]["code"], e["error"]["message"], started_at=started)
        return e

def search_museum_objects(q, hasImages=None, title=None, departmentId=None, **_extra):
    import json, os, datetime, time, hashlib, urllib.parse, urllib.request

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0211000" if __import__("os").path.isdir("./environment_mix/0211000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, latency_ms, **fields):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now() + "|" + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "status": int(status_code),
            "latency_ms": int(latency_ms),
            "created_at": _now(),
        }
        row.update(fields)
        logs.append(row)
        _save("request_logs.json", logs)

    start = time.time()
    endpoint = "search-museum-objects"

    # Validate
    if not isinstance(q, str) or not q.strip():
        latency = int((time.time() - start) * 1000)
        _log(endpoint, 400, latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "q is required and must be a non-empty string.")
    if hasImages is None:
        hasImages = False
    if title is None:
        title = False
    if not isinstance(hasImages, bool):
        latency = int((time.time() - start) * 1000)
        _log(endpoint, 400, latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hasImages must be a boolean.")
    if not isinstance(title, bool):
        latency = int((time.time() - start) * 1000)
        _log(endpoint, 400, latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a boolean.")
    if hasImages is True and title is True:
        latency = int((time.time() - start) * 1000)
        _log(endpoint, 400, latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid combination: hasImages=true and title=true cannot both be set.")

    dep_met_id = None
    if departmentId is not None:
        # JSON schema says number; accept ints that are not bool.
        if isinstance(departmentId, bool):
            latency = int((time.time() - start) * 1000)
            _log(endpoint, 400, latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "departmentId must be a positive number.")
        if isinstance(departmentId, (int, float)):
            if int(departmentId) != departmentId:
                latency = int((time.time() - start) * 1000)
                _log(endpoint, 400, latency, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "departmentId must be an integer.")
            dep_met_id = int(departmentId)
            if dep_met_id <= 0:
                latency = int((time.time() - start) * 1000)
                _log(endpoint, 400, latency, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "departmentId must be a positive integer.")
        else:
            latency = int((time.time() - start) * 1000)
            _log(endpoint, 400, latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "departmentId must be a number.")

    departments = _load("departments.json")
    if not isinstance(departments, list):
        departments = []
    dep_id = None
    if dep_met_id is not None:
        for d in departments:
            if isinstance(d, dict) and d.get("met_department_id") == dep_met_id:
                dep_id = d.get("id")
                break
        # Chosen consistent behavior: NOT_FOUND if departmentId does not exist in departments cache.
        if dep_id is None:
            latency = int((time.time() - start) * 1000)
            _log(endpoint, 404, latency, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "departmentId not found in cached departments. Call list-departments first or omit departmentId.")

    # Create search query row (queued -> running -> succeeded|failed)
    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []
    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []

    now = _now()
    sq_id = "sq_" + hashlib.sha256((q.strip() + "|" + now + "|" + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:24]
    sq_row = {
        "id": sq_id,
        "q": q,
        "has_images": bool(hasImages),
        "title": bool(title),
        "department_met_id": dep_met_id,
        "department_id": dep_id,
        "status": "queued",
        "result_total": None,
        "upstream_request_url": None,
        "error_code": None,
        "error_message": None,
        "completed_at": None,
        "created_at": now,
        "updated_at": now,
    }
    search_queries.append(sq_row)
    _save("search_queries.json", search_queries)

    # Transition queued -> running
    sq_row["status"] = "running"
    sq_row["updated_at"] = _now()
    _save("search_queries.json", search_queries)

    # Upstream request
    params = {"q": q}
    if hasImages:
        params["hasImages"] = "true"
    if title:
        params["title"] = "true"
    if dep_met_id is not None:
        params["departmentId"] = str(dep_met_id)
    upstream_url = "https://collectionapi.metmuseum.org/public/collection/v1/search?" + urllib.parse.urlencode(params)
    sq_row["upstream_request_url"] = upstream_url
    sq_row["updated_at"] = _now()
    _save("search_queries.json", search_queries)

    try:
        req = urllib.request.Request(upstream_url, headers={"User-Agent": "met-museum-server/1.0"})
        with urllib.request.urlopen(req, timeout=12) as resp:
            body = resp.read()
        data = json.loads(body.decode("utf-8"))
    except Exception as e:
        sq_row["status"] = "failed"
        sq_row["error_code"] = "UPSTREAM_ERROR"
        sq_row["error_message"] = str(e)
        sq_row["completed_at"] = _now()
        sq_row["updated_at"] = sq_row["completed_at"]
        _save("search_queries.json", search_queries)
        latency = int((time.time() - start) * 1000)
        _log(endpoint, 502, latency, search_query_id=sq_id, error_code="UPSTREAM_ERROR")
        return _err("CONFLICT", "Upstream search failed.", searchQueryId=sq_id)

    total = data.get("total")
    object_ids = data.get("objectIDs")
    if not isinstance(total, int) or total < 0:
        # Normalize as failed
        sq_row["status"] = "failed"
        sq_row["error_code"] = "UPSTREAM_MALFORMED"
        sq_row["error_message"] = "Upstream response missing/invalid total."
        sq_row["completed_at"] = _now()
        sq_row["updated_at"] = sq_row["completed_at"]
        _save("search_queries.json", search_queries)
        latency = int((time.time() - start) * 1000)
        _log(endpoint, 502, latency, search_query_id=sq_id, error_code="UPSTREAM_MALFORMED")
        return _err("CONFLICT", "Upstream response malformed.", searchQueryId=sq_id)

    if object_ids is None:
        object_ids = []
    if not isinstance(object_ids, list):
        sq_row["status"] = "failed"
        sq_row["error_code"] = "UPSTREAM_MALFORMED"
        sq_row["error_message"] = "Upstream response missing/invalid objectIDs."
        sq_row["completed_at"] = _now()
        sq_row["updated_at"] = sq_row["completed_at"]
        _save("search_queries.json", search_queries)
        latency = int((time.time() - start) * 1000)
        _log(endpoint, 502, latency, search_query_id=sq_id, error_code="UPSTREAM_MALFORMED")
        return _err("CONFLICT", "Upstream response malformed.", searchQueryId=sq_id)

    # Insert results enforcing uniqueness (search_query_id, met_object_id) and (search_query_id, rank)
    existing_pairs = set()
    for r in search_results:
        if isinstance(r, dict):
            if r.get("search_query_id") == sq_id:
                existing_pairs.add((r.get("met_object_id"), r.get("rank")))

    museum_objects = _load("museum_objects.json")
    if not isinstance(museum_objects, list):
        museum_objects = []
    mo_by_met = {}
    for mo in museum_objects:
        if isinstance(mo, dict) and isinstance(mo.get("met_object_id"), int):
            mo_by_met[mo["met_object_id"]] = mo.get("id")

    inserted = 0
    now2 = _now()
    for idx, oid in enumerate(object_ids, start=1):
        if not isinstance(oid, int) or oid <= 0:
            continue
        if (oid, idx) in existing_pairs:
            continue
        # Ensure no duplicate met_object_id for this query
        if any(isinstance(r, dict) and r.get("search_query_id") == sq_id and r.get("met_object_id") == oid for r in search_results):
            continue
        sr_id = "sr_" + hashlib.sha256((sq_id + "|" + str(oid) + "|" + str(idx)).encode("utf-8")).hexdigest()[:24]
        search_results.append({
            "id": sr_id,
            "search_query_id": sq_id,
            "met_object_id": oid,
            "museum_object_id": mo_by_met.get(oid),
            "rank": idx,
            "created_at": now2,
            "updated_at": now2,
        })
        inserted += 1

    _save("search_results.json", search_results)

    # Transition running -> succeeded
    sq_row["status"] = "succeeded"
    sq_row["result_total"] = total
    sq_row["completed_at"] = _now()
    sq_row["updated_at"] = sq_row["completed_at"]
    _save("search_queries.json", search_queries)

    latency = int((time.time() - start) * 1000)
    _log(endpoint, 200, latency, search_query_id=sq_id, total=total, returned=len(object_ids))

    return {
        "data": {
            "searchQueryId": sq_id,
            "total": total,
            "objectIDs": object_ids,
        }
    }

def get_search_query(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0211000" if __import__("os").path.isdir("./environment_mix/0211000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(v):
        if not isinstance(v, str):
            return None
        try:
            s = v[:-1] if v.endswith("Z") else v
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log_request(endpoint, t0, status_code, error_code=None, **fields):
        logs = _ensure_logs()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": int(status_code),
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        if error_code:
            row["error_code"] = error_code
        row.update(fields)
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits(endpoint, t0):
        logs = _ensure_logs()
        now_dt = datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        recent_1m = 0
        recent_24h = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("created_at")) or _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_1m += 1
            if ts >= day_ago:
                recent_24h += 1

        if recent_1m >= 120:
            _log_request(endpoint, t0, 429, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit="120/min")
        if recent_24h >= 10000:
            _log_request(endpoint, t0, 429, error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit="10000/day")
        return None

    t0 = time.time()
    endpoint = "get-search-query"

    # Validate
    if not isinstance(id, str) or not id.strip():
        err = _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a non-empty string.", field="id")
        _log_request(endpoint, t0, 400, error_code=err["error"]["code"])
        return err
    id = id.strip()

    # Rate limit / quota
    lim = _check_limits(endpoint, t0)
    if lim:
        return lim

    # Load and find
    qs = _load("search_queries.json")
    if not isinstance(qs, list):
        qs = []
    row = None
    for r in qs:
        if isinstance(r, dict) and r.get("id") == id:
            row = r
            break

    # Read tools: empty match -> NOT_FOUND per tool spec
    if row is None:
        err = _err("NOT_FOUND", "No search query exists for the given id.", id=id)
        _log_request(endpoint, t0, 404, error_code=err["error"]["code"], search_query_id=id)
        return err

    _log_request(endpoint, t0, 200, search_query_id=id)
    return {"data": row}

def list_search_queries(status=None, departmentId=None, hasImages=None, title=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0211000" if __import__("os").path.isdir("./environment_mix/0211000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request log / rate limit / quota (best-effort if collection exists) ---
    def _log_and_maybe_limit(endpoint, status_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        # Simple global rate limit: 120 requests/minute across the whole service.
        # Simple daily quota: 10,000 requests/day.
        # Enforced only if request_logs collection exists (or is creatable here).
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0)
