        return err

    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []

    # Filter + order by rank ascending
    filtered = [r for r in results if isinstance(r, dict) and r.get("search_query_id") == searchQueryId]
    filtered.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**18, r.get("id") or ""))

    # Pagination by cursor (cursor is an opaque "start after id" token)
    start_idx = 0
    if cursor is not None:
        for i, r in enumerate(filtered):
            if r.get("id") == cursor:
                start_idx = i + 1
                break
        else:
            # Cursor not found in this result set -> treat as validation error (invalid cursor)
            err = _err("VALIDATION_ERROR", "Invalid cursor for this searchQueryId.", field="cursor", cursor=cursor)
            _log_request(endpoint, t0, 400, error_code=err["error"]["code"], search_query_id=searchQueryId)
            return err

    page = filtered[start_idx : start_idx + limit]
    has_more = start_idx + limit < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    _log_request(endpoint, t0, 200, search_query_id=searchQueryId)
    return {
        "data": page,
        "meta": {
            "search_query_id": searchQueryId,
            "total": len(filtered),
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
