            if ts >= day_ago:
                recent_24h += 1

        if recent_1m >= 120:
            logs.append({"id": f"req_{int(time.time()*1000)}", "endpoint": endpoint, "timestamp": now, "status": "RATE_LIMIT", "latency_ms": int((time.time()-t0)*1000)})
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit="120/min")
        if recent_24h >= 10000:
            logs.append({"id": f"req_{int(time.time()*1000)}", "endpoint": endpoint, "timestamp": now, "status": "QUOTA_EXCEEDED", "latency_ms": int((time.time()-t0)*1000)})
            _save("request_logs.json", logs)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota="10000/day")

        logs.append({"id": f"req_{int(time.time()*1000)}", "endpoint": endpoint, "timestamp": now, "status": status_code, "latency_ms": int((time.time()-t0)*1000)})
        _save("request_logs.json", logs)
        return None

    endpoint = "update-department"

    # validate
    if not isinstance(id, str) or not id.strip():
        e = _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
        _log_and_maybe_limit(endpoint, "VALIDATION_ERROR")
        return e

    if status not in ("active", "inactive"):
        e = _err("VALIDATION_ERROR", "Invalid status.", field="status")
        _log_and_maybe_limit(endpoint, "VALIDATION_ERROR")
        return e

    depts = _load("departments.json")
    if not isinstance(depts, list):
        depts = []

    idx = None
    row = None
    for i, r in enumerate(depts):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            row = r
            break

    if row is None:
        e = _err("NOT_FOUND", "Department not found.", id=id)
        _log_and_maybe_limit(endpoint, "NOT_FOUND")
        return e

    current = row.get("status")
    if current not in ("active", "inactive"):
        e = _err("CONFLICT", "Department is in an unknown lifecycle state.", current_status=current)
        _log_and_maybe_limit(endpoint, "CONFLICT")
        return e

    if current == status:
        # idempotent update with effect? Treat as success with unchanged row.
        resp = {"data": row, "meta": {"idempotent": True}}
        lim_err = _log_and_maybe_limit(endpoint, "OK")
        if lim_err:
            return lim_err
        return resp

    allowed = {"active": ["inactive"], "inactive": ["active"]}
    if status not in allowed.get(current, []):
        e = _err("INVALID_TRANSITION", "Requested status transition is not allowed.", from_status=current, to_status=status)
        _log_and_maybe_limit(endpoint, "INVALID_TRANSITION")
        return e

    # apply
    depts[idx]["status"] = status
    depts[idx]["updated_at"] = now
    _save("departments.json", depts)

    resp = {"data": depts[idx]}
    lim_err = _log_and_maybe_limit(endpoint, "OK")
    if lim_err:
        return lim_err
    return resp

def update_resource(id, status, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0211000" if __import__("os").path.isdir("./environment_mix/0211000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(v):
        if not isinstance(v, str):
            return None
        try:
            s = v[:-1] if v.endswith("Z") else v
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log_request(endpoint, t0, status_code, error_code=None, **fields):
        logs = _ensure_logs()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": int(status_code),
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        if error_code:
            row["error_code"] = error_code
        row.update(fields)
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits(endpoint, t0):
        logs = _ensure_logs()
        now_dt = datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        recent_1m = 0
        recent_24h = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("created_at")) or _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_1m += 1
            if ts >= day_ago:
                recent_24h += 1

        if recent_1m >= 120:
            _log_request(endpoint, t0, 429, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit="120/min")
        if recent_24h >= 10000:
            _log_request(endpoint, t0, 429, error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit="10000/day")
        return None

    t0 = time.time()
    endpoint = "update-resource"

    # Validate
    if not isinstance(id, str) or not id.strip():
        err = _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a non-empty string.", field="id")
        _log_request(endpoint, t0, 400, error_code=err["error"]["code"])
        return err
    id = id.strip()

    allowed_status = {"pending", "available", "failed", "deleted"}
    if not isinstance(status, str) or status not in allowed_status:
        err = _err(
            "VALIDATION_ERROR",
            "Parameter 'status' must be one of: pending, available, failed, deleted.",
            field="status",
        )
        _log_request(endpoint, t0, 400, error_code=err["error"]["code"], resource_id=id)
        return err

    # Rate limit / quota
    lim = _check_limits(endpoint, t0)
    if lim:
        return lim

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    idx = None
    for i, r in enumerate(resources):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            break

    if idx is None:
        err = _err("NOT_FOUND", "No resource exists for the given id.", id=id)
        _log_request(endpoint, t0, 404, error_code=err["error"]["code"], resource_id=id)
        return err

    row = resources[idx]
    current = row.get("status")
    if current not in allowed_status:
        err = _err("CONFLICT", "Resource has an unknown or invalid current status and cannot be transitioned.", id=id, current_status=current)
        _log_request(endpoint, t0, 409, error_code=err["error"]["code"], resource_id=id)
        return err

    transitions = {
        "pending": {"available", "failed", "deleted"},
        "available": {"deleted"},
        "failed": {"pending", "deleted"},
        "deleted": set(),
    }

    if status == current:
        # Idempotent update
        _log_request(endpoint, t0, 200, resource_id=id)
        return {"data": row}

    if status not in transitions.get(current, set()):
        err = _err(
            "CONFLICT",
            "Requested status transition is not allowed by the resource lifecycle rules.",
            id=id,
            from_status=current,
            to_status=status,
            allowed=sorted(list(transitions.get(current, set()))),
        )
        _log_request(endpoint, t0, 409, error_code=err["error"]["code"], resource_id=id)
        return err

    now = _now_iso()
    row["status"] = status
    row["updated_at"] = now

    # Business-ish: retry clears error_message when moving back to pending
    if current == "failed" and status == "pending":
        if "error_message" in row:
            row["error_message"] = None

    resources[idx] = row
    _save("resources.json", resources)

    _log_request(endpoint, t0, 200, resource_id=id)
    return {"data": row}
